def find_max(words):
    def unique_count(word):
        return len(set(word))

    max_unique = -1
    result_word = ""

    for word in words:
        unique_chars = unique_count(word)
        if unique_chars > max_unique or (unique_chars == max_unique and word < result_word):
            max_unique = unique_chars
            result_word = word

    return result_word
